.cs-taskbox {
  margin-top: 12px;
  padding: 12px 14px;
  border-radius: 12px;
  border: 1px solid rgba(94, 234, 212, 0.4);
  background: linear-gradient(135deg, rgba(45, 212, 191, 0.12), rgba(34, 197, 94, 0.12));
}
.cs-taskbox__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
  color: var(--text, #0f172a);
  font-weight: 700;
  letter-spacing: 0.01em;
}
.cs-taskbox__actions {
  display: flex;
  gap: 6px;
}
.cs-taskbox__button {
  border: 1px solid rgba(94, 234, 212, 0.6);
  background: rgba(15, 23, 42, 0.6);
  color: #ecfeff;
  border-radius: 8px;
  padding: 5px 10px;
  font-size: 0.85rem;
  cursor: pointer;
  transition: transform 120ms ease, background 120ms ease;
}
.cs-taskbox__button:hover {
  transform: translateY(-1px);
  background: rgba(16, 185, 129, 0.6);
}
.cs-taskbox__list {
  display: grid;
  gap: 6px;
  margin: 0;
  padding-left: 4px;
}
.cs-taskbox__item {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.08);
}
.cs-taskbox__item label {
  display: contents;
  cursor: pointer;
}
.cs-taskbox__item input[type='checkbox'] {
  accent-color: #10b981;
  width: 16px;
  height: 16px;
}
.cs-taskbox__item .cs-taskbox__text {
  color: var(--text, #0f172a);
  opacity: 0.92;
}
.cs-taskbox__item .cs-taskbox__delete {
  border: none;
  background: transparent;
  color: rgba(148, 163, 184, 0.8);
  cursor: pointer;
}
.cs-taskbox__item .cs-taskbox__delete:hover {
  color: #ef4444;
}
.cs-taskbox__progress {
  font-size: 0.85rem;
  opacity: 0.82;
}

