(function() {
  'use strict';
  if (window.__CS_CARD_TASKBOX__) return;
  window.__CS_CARD_TASKBOX__ = true;

  const api = window.CardSpoke?.utils;
  const storageKey = 'cs-taskbox-v2';

  const loadState = () => {
    try {
      return JSON.parse(localStorage.getItem(storageKey) || '{}');
    } catch (e) {
      console.warn('Taskbox: failed to load state', e);
      return {};
    }
  };

  const saveState = (state) => {
    try {
      localStorage.setItem(storageKey, JSON.stringify(state));
    } catch (e) {
      console.warn('Taskbox: failed to save state', e);
    }
  };

  const state = loadState();

  const getCardId = (el, idx) => el?.dataset?.cardId || el?.getAttribute('data-id') || el?.id || `card-${idx}`;

  const renderCard = (card, idx) => {
    const body = card.querySelector('.card-body, .card-detail-body');
    if (!body) return;

    const cardId = getCardId(card, idx);
    state[cardId] = state[cardId] || [];

    let box = body.querySelector('.cs-taskbox');
    if (!box) {
      box = document.createElement('div');
      box.className = 'cs-taskbox';
      body.appendChild(box);
    } else {
      box.innerHTML = '';
    }

    const header = document.createElement('div');
    header.className = 'cs-taskbox__header';
    const title = document.createElement('span');
    title.textContent = 'Taskbox';
    const progress = document.createElement('span');
    progress.className = 'cs-taskbox__progress';
    const completed = state[cardId].filter((t) => t.done).length;
    progress.textContent = state[cardId].length ? `${completed}/${state[cardId].length} done` : 'No tasks yet';
    header.appendChild(title);
    header.appendChild(progress);

    const actions = document.createElement('div');
    actions.className = 'cs-taskbox__actions';
    const addBtn = document.createElement('button');
    addBtn.className = 'cs-taskbox__button';
    addBtn.textContent = 'Add task';
    addBtn.addEventListener('click', () => {
      const text = prompt('Task to add to this card?');
      if (!text) return;
      state[cardId].push({ text, done: false });
      saveState(state);
      renderCard(card, idx);
    });

    const clearBtn = document.createElement('button');
    clearBtn.className = 'cs-taskbox__button';
    clearBtn.textContent = 'Clear done';
    clearBtn.addEventListener('click', () => {
      state[cardId] = state[cardId].filter((t) => !t.done);
      saveState(state);
      renderCard(card, idx);
    });

    actions.appendChild(addBtn);
    actions.appendChild(clearBtn);
    header.appendChild(actions);
    box.appendChild(header);

    const list = document.createElement('div');
    list.className = 'cs-taskbox__list';
    state[cardId].forEach((item, itemIdx) => {
      const row = document.createElement('div');
      row.className = 'cs-taskbox__item';

      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = !!item.done;
      checkbox.addEventListener('change', () => {
        state[cardId][itemIdx].done = checkbox.checked;
        saveState(state);
        renderCard(card, idx);
      });

      const text = document.createElement('span');
      text.className = 'cs-taskbox__text';
      text.textContent = item.text;

      const del = document.createElement('button');
      del.className = 'cs-taskbox__delete';
      del.textContent = '✕';
      del.title = 'Remove task';
      del.addEventListener('click', () => {
        state[cardId].splice(itemIdx, 1);
        saveState(state);
        renderCard(card, idx);
      });

      row.appendChild(checkbox);
      row.appendChild(text);
      row.appendChild(del);
      list.appendChild(row);
    });

    box.appendChild(list);
  };

  const renderAll = () => {
    const cards = document.querySelectorAll('.card, .card-detail');
    cards.forEach((card, idx) => renderCard(card, idx));
  };

  const observer = new MutationObserver(() => setTimeout(renderAll, 80));

  const enable = () => {
    observer.observe(document.body, { childList: true, subtree: true });
    renderAll();
    api?.showToast?.('Card Taskbox ready — add checkboxes to any card', 'success');
  };

  const disable = () => {
    observer.disconnect();
    document.querySelectorAll('.cs-taskbox').forEach((el) => el.remove());
  };

  if (window.CardSpoke_MODS?.register) {
    CardSpoke_MODS.register('plugin-card-taskbox', {
      meta: { name: 'Card Taskbox', type: 'Plugin', version: '1.1.0' },
      onAppInit: enable,
      onCardRender() { setTimeout(renderAll, 10); },
      onDisable: disable,
      onUninstall: disable
    });
  } else {
    enable();
  }
})();
